				reg = <1>;
				remote-endpoint = <&panel_in>;
			};
		};
	};

	dpi_panel: panel@0 {
			status = "ok";
			compatible = "raspberrypi,dpi-panel";
	};
};

&lcds {
	status = "okay";
};

&dpu_online2_hdmi {
	memory-region = <&dpu_resv>;
	status = "okay";
};

&hdmi{
	pinctrl-names = "default";
	pinctrl-0 = <&pinctrl_hdmi_0>;
	status = "okay";
};

&i2c0 {
	pinctrl-names = "default";
	pinctrl-0 = <&pinctrl_i2c0>;
	spacemit,i2c-fast-mode;
	status = "okay";
};

&i2c1 {
