	raspits-panel@45 {
		status = "okay";
		compatible = "raspberrypi,7inch-touchscreen-panel";
		reg = <0x45>;
		enable-gpio = <&gpio 83 0>;

		port {
			panel_in: endpoint {
				remote-endpoint = <&dsi1_output>;
