add("| SHUB_UART1 | 0xC088_D000 | RCPU 串口 1（带自动流控） |");
add("| CODEC/SSPA ADMA | 0xC088_3000/0x3100 | 音频 DMA/串行端口 |");
add("| I2S/HDMI ADMA | 0xC088_3400+ | 音频通路 |");
add("| AHBDMA | 0xC088_4000 | 16 通道 DMA |");
add("| SHUB_SSP0/1 (SPI) | 0xC088_5000/0x6000 | rspi0/rspi1 |");
